<?php

declare(strict_types=1);

namespace App\Hosts\Protocol;

use App\Attributes\AutoGenerated;

/**
 * Every call the host makes to the journal in host protocol 1, by its name.
 * Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.
 */
#[AutoGenerated('protocol/host.json')]
enum HostRoute: string
{
    case ClaimOrders = 'claim_orders';
    case AnswerOrder = 'answer_order';
    case PullPrivateValue = 'pull_private_value';
    case NotifyProcessOutput = 'notify_process_output';
    case NotifyProcessReport = 'notify_process_report';
    case NotifyInventory = 'notify_inventory';
    case NotifyHeartbeat = 'notify_heartbeat';
    case NotifyProjectRead = 'notify_project_read';

    /**
     * Whether the path, without its query, is this call's.
     */
    public function matchesPath(string $path): bool
    {
        return preg_match(match ($this) {
            self::ClaimOrders => '#^/host/orders/claim$#',
            self::AnswerOrder => '#^/host/orders/[^/]+$#',
            self::PullPrivateValue => '#^/host/private\-values/[^/]+$#',
            self::NotifyProcessOutput => '#^/host/processes/[^/]+/output$#',
            self::NotifyProcessReport => '#^/host/processes/[^/]+$#',
            self::NotifyInventory => '#^/host/inventory$#',
            self::NotifyHeartbeat => '#^/host/heartbeat$#',
            self::NotifyProjectRead => '#^/host/reports/project\-reads/[^/]+$#',
        }, $path) === 1;
    }

    /**
     * The Data of the body the host sends with this call.
     *
     * @return class-string<\Spatie\LaravelData\Data>
     */
    public function bodyData(): string
    {
        return match ($this) {
            self::ClaimOrders => Data\HostNothingData::class,
            self::AnswerOrder => Data\HostAnswerData::class,
            self::PullPrivateValue => Data\HostNothingData::class,
            self::NotifyProcessOutput => Data\HostOutputData::class,
            self::NotifyProcessReport => Data\HostProcessReportData::class,
            self::NotifyInventory => Data\HostInventoryData::class,
            self::NotifyHeartbeat => Data\HostHeartbeatData::class,
            self::NotifyProjectRead => Data\HostProjectReadReportData::class,
        };
    }

    /**
     * The Data of the journal's answer to this call.
     *
     * @return class-string<\Spatie\LaravelData\Data>
     */
    public function replyData(): string
    {
        return match ($this) {
            self::ClaimOrders => Data\HostClaimedOrdersData::class,
            self::AnswerOrder => Data\HostNothingData::class,
            self::PullPrivateValue => Data\HostPrivateValueData::class,
            self::NotifyProcessOutput => Data\HostNothingData::class,
            self::NotifyProcessReport => Data\HostNothingData::class,
            self::NotifyInventory => Data\HostNothingData::class,
            self::NotifyHeartbeat => Data\HostNothingData::class,
            self::NotifyProjectRead => Data\HostNothingData::class,
        };
    }
}
